"workflow": {
  "title": "vendor onboarding for small manufacturing company",
  "summary": "procurement employee submits supplier request; ai assistant analyzes and recommends; procurement manager reviews; finance verifies bank details; authorized employee adds vendor to system; rejection returns request, acceptance creates onboarding record without order placement. workflow lacks defined api permissions, retention periods, and escalation deadlines."
},
"evidence": [
  {"id": "ev-1", "quote": "A procurement employee submits a supplier request with a quotation, company details and a proposed order value."},
  {"id": "ev-2", "quote": "An AI assistant reads the quotation and supplier record, compares the request with the approved supplier list, and prepares a recommendation."},
  {"id": "ev-3", "quote": "The procurement manager reviews the recommendation."},
  {"id": "ev-4", "quote": "Finance verifies bank details through a separate established channel."},
  {"id": "ev-5", "quote": "Only an authorised procurement employee can add a vendor to the purchasing system."},
  {"id": "ev-6", "quote": "The assistant cannot change bank details, add a vendor, place an order or send a payment."},
  {"id": "ev-7", "quote": "Requests involving missing or conflicting records are paused for review."},
  {"id": "ev-8", "quote": "A rejection returns the request to the requester with an explanation; acceptance creates a reviewed onboarding record, not an order."},
  {"id": "ev-9", "quote": "The workflow will use a supplier register and a purchasing system, but the exact products and API permissions are not yet defined."},
  {"id": "ev-10", "quote": "Operating countries, document retention periods, escalation deadlines, record ownership and budget thresholds still need to be decided."}
],
"facts": [
  {"id": "fact-1", "evidence_ids": ["ev-1", "ev-2", "ev-3", "ev-4", "ev-5", "ev-6", "ev-7", "ev-8"]},
  {"id": "fact-2", "evidence_ids": ["ev-9", "ev-10"]}
],
